"درس ۱۳: نارنج و برنج":{"title":"درس ۱۳: نارنج و برنج — آموزش خواندن و نوشتن","goals":["نشانه‌های معرفی‌شده را در واژه تشخیص دهد.","صدای نشانه را درست و روشن ادا کند.","واژه‌های ساده را بخش‌بندی و پیوسته‌خوانی کند.","با واژه‌های آموخته‌شده جمله بسازد و آن را بنویسد."],"prerequisites":["گوش‌دادن به صدای واژه‌ها","تمرین دیداری و شنیداری نشانه‌های پیشین"],"explanation":[{"head":"نشانه‌های این درس","body":"نشانه‌های مورد تمرین: ج. هر نشانه را ببین، نام و صدایش را بگو و شکل آن را در واژه پیدا کن."},{"head":"واژه‌خوانی","body":"واژه‌های نمونه: جوجه، جوراب، جنگل، برنج. ابتدا آرام بخوان، سپس بخش‌ها را به هم پیوند بده و واژه را روان تکرار کن."},{"head":"خواندن جمله","body":"جوجه کنار مادرش راه می‌رود. برنج در بشقاب است. جمله را از راست به چپ بخوان و در پایان مکث کن."},{"head":"نوشتن","body":"نشانه را با اندازه مناسب بنویس. جای نشانه در آغاز، میان یا پایان واژه را مقایسه کن و سپس واژه را کامل بنویس."},{"head":"فهم معنا","body":"پس از خواندن واژه یا جمله، معنی آن را با زبان خودت توضیح بده؛ فقط صداخوانی کافی نیست."}],"examples":[{"title":"خواندن واژه","problem":"جوجه","steps":["نشانه‌های واژه را جداگانه نگاه می‌کنیم.","صداها را به ترتیب می‌خوانیم.","صداها را پیوسته می‌کنیم و واژه را می‌گوییم."],"answer":"جوجه پرنده‌ای کوچک است."},{"title":"خواندن جمله","problem":"جوجه کنار مادرش راه می‌رود.","steps":["واژه‌ها را از راست به چپ می‌خوانیم.","بین واژه‌ها مکث کوتاه می‌کنیم.","معنی جمله را با زبان خود می‌گوییم."],"answer":"جوجه کنار مادرش راه می‌رود."}],"mistakes":["حدس‌زدن واژه بدون توجه به همه نشانه‌ها.","جا انداختن صدای کوتاه یا کشیده.","شتاب‌زدگی در پیوسته‌خوانی.","نوشتن شکل نشانه در جای نادرست."],"keyPoints":["نشانه را با صدا و شکل آن یاد بگیر.","واژه را بخش‌بندی و سپس پیوسته‌خوانی کن.","معنی جمله را هم بفهم.","هر روز چند دقیقه با صدای بلند بخوان."],"exercises":[{"level":"آسان","q":"نشانه تازه این درس چیست؟ (ج)","answer":"ج","explain":"نشانه‌ها را با صدای درست و چند بار بلند بخوان."},{"level":"آسان","q":"واژه «جوجه» را بخوان و معنی کن.","answer":"جوجه پرنده‌ای کوچک است.","explain":"واژه جوجه را به‌آرامی بخوان و با معنی آن پیوند بده."},{"level":"متوسط","q":"با ج یک واژه بگو.","answer":"جوجه.","explain":"ج در آغاز جوجه است."},{"level":"متوسط","q":"با «جنگل» جمله بساز.","answer":"جنگل خانه جانوران بسیاری است.","explain":"جنگل"},{"level":"چالشی","q":"چرا باید از درختان جنگل مراقبت کنیم؟","answer":"چون خانه جانوران و بخشی از طبیعت‌اند.","explain":"حفاظت از جنگل به طبیعت کمک می‌کند."},{"level":"چالشی","q":"با دو واژه «جوجه» و «جنگل» یک گفت‌وگوی کوتاه بساز.","answer":"پاسخ آزاد؛ هر دو واژه باید درست و در جمله‌های مرتبط استفاده شوند.","explain":"برای گفت‌وگوی خوب، پرسش و پاسخ باید به یک موضوع مربوط باشند."}],"memoryAnswer":"نشانه‌ها: ج. واژه‌های نمونه: جوجه، جوراب، جنگل، برنج. بخوان، بخش‌بندی کن، پیوسته بخوان و معنی را بگو.","quiz":[{"q":"کدام گزینه واژه نمونه این درس است؟","options":["جوجه","جنگل","مداد"],"answer":0,"explain":"جوجه یکی از واژه‌های تمرینی این درس است."},{"q":"پس از خواندن جمله چه کاری انجام می‌دهیم؟","options":["معنی آن را می‌گوییم","نشانه‌ها را نادیده می‌گیریم","واژه‌ها را جابه‌جا می‌کنیم"],"answer":0,"explain":"خواندن باید همراه با فهم معنا باشد."}],"status":"draft_original_content"},
